import React, { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "../context/AuthContext";
import "./Home.css";

const Home = () => {
  const { user } = useContext(AuthContext);
  const navigate = useNavigate();
  const [complaint, setComplaint] = useState("");
  const [complaintsList, setComplaintsList] = useState([]);

  const handleAddComplaint = () => {
    if (complaint.trim() !== "") {
      setComplaintsList([...complaintsList, complaint]);
      setComplaint("");
    }
  };

  const handleGoToEmergency = () => {
    navigate("/emergency");
  };

  return (
    <div className="home-container">
      {/* ✅ FIXED LINE */}
      <h1 className="home-title">
        Welcome, {user ? user.username : "Guest"}!
      </h1>

      <div className="home-section">
        <h2>Complaints</h2>
        <input
          type="text"
          placeholder="Enter your complaint"
          value={complaint}
          onChange={(e) => setComplaint(e.target.value)}
          className="input-field"
        />
        <button onClick={handleAddComplaint} className="btn">
          Add Complaint
        </button>

        <ul className="complaints-list">
          {complaintsList.map((item, index) => (
            <li key={index}>{item}</li>
          ))}
        </ul>
      </div>

      <div className="home-section">
        <h2>Emergency Contacts</h2>
        <p>Click below to view emergency contacts</p>
        <button onClick={handleGoToEmergency} className="btn">
          Go to Emergency Contacts
        </button>
      </div>
    </div>
  );
};

export default Home;
